<script setup>
import { computed,ref,onMounted } from 'vue'; import axios from 'axios'; import { router } from '@inertiajs/vue3';
const props=defineProps({lessonId:Number,maxBytes:Number}); const title=ref(''); const file=ref(null); const session=ref(null); const state=ref('idle'); const error=ref(''); const uploaded=ref(0); const key=`video-upload:${props.lessonId}`;
const percent=computed(()=>file.value?Math.floor(uploaded.value/file.value.size*100):0); const format=n=>`${(n/1024/1024).toFixed(1)} مگابایت`;
onMounted(()=>{const saved=localStorage.getItem(key);if(saved){session.value=JSON.parse(saved);uploaded.value=session.value.uploaded_bytes||0;state.value='resume';}});
function choose(e){file.value=e.target.files[0]||null;error.value='';if(file.value&&file.value.size>props.maxBytes){error.value='حجم فایل بیشتر از حد مجاز است.';file.value=null;}}
async function start(){if(!file.value||!title.value)return error.value='عنوان و فایل را انتخاب کنید.';state.value='starting';try{const {data}=await axios.post(`/lessons/${props.lessonId}/video-uploads`,{title:title.value,original_filename:file.value.name,declared_mime_type:file.value.type,total_bytes:file.value.size});session.value=data;uploaded.value=data.expected_offset;localStorage.setItem(key,JSON.stringify(data));await upload();}catch(e){fail(e);}}
async function resume(){if(!file.value)return error.value='برای ادامه همان فایل را دوباره انتخاب کنید.';if(file.value.name!==session.value.original_filename||file.value.size!==session.value.total_bytes)return error.value='فایل انتخاب‌شده با session قبلی مطابقت ندارد.';try{const {data}=await axios.get(`/video-uploads/${session.value.id}`);session.value=data;uploaded.value=data.expected_offset;await upload();}catch(e){fail(e);}}
async function upload(){state.value='uploading';error.value='';while(uploaded.value<file.value.size){const end=Math.min(uploaded.value+session.value.chunk_size,file.value.size);const blob=file.value.slice(uploaded.value,end);try{const {data}=await axios.patch(`/video-uploads/${session.value.id}/chunk`,blob,{headers:{'Content-Type':'application/octet-stream','Upload-Offset':uploaded.value}});uploaded.value=data.expected_offset;session.value=data;localStorage.setItem(key,JSON.stringify(data));}catch(e){if(e.response?.status===409){uploaded.value=e.response.data.expected_offset;continue;}state.value='retry';return fail(e);}}await finish();}
async function finish(){state.value='finalizing';try{await axios.post(`/video-uploads/${session.value.id}/finalize`);localStorage.removeItem(key);state.value='done';router.reload({only:['lesson']});}catch(e){fail(e);}}
async function cancel(){if(session.value)await axios.delete(`/video-uploads/${session.value.id}`);localStorage.removeItem(key);session.value=null;file.value=null;uploaded.value=0;state.value='idle';}
function fail(e){error.value=e.response?.data?.message||'ارتباط با سرور قطع شد؛ دوباره تلاش کنید.';if(state.value!=='retry')state.value='error';}
</script>
<template><div class="rounded-xl border p-4"><h3 class="font-bold">افزودن ویدئو</h3><div class="mt-3 space-y-3"><input v-model="title" placeholder="عنوان نمایشی ویدئو" :disabled="!!session"><input type="file" accept="video/mp4,video/quicktime,.m4v" @change="choose"><div v-if="file" class="text-sm text-slate-600"><p>{{ file.name }} — {{ format(file.size) }}</p></div><div v-if="session" class="space-y-2"><div class="h-3 overflow-hidden rounded-full bg-slate-200"><div class="h-full bg-teal-600" :style="{width:`${percent}%`}"></div></div><p class="text-sm">{{ format(uploaded) }} از {{ format(session.total_bytes) }} — {{ percent }}٪</p></div><p v-if="error" class="text-sm text-red-600">{{ error }}</p><div class="flex flex-wrap gap-2"><button v-if="state==='idle'" @click="start" class="rounded-xl bg-teal-700 px-4 py-2 text-white">شروع بارگذاری</button><button v-if="['resume','retry','error'].includes(state)&&session" @click="resume" class="rounded-xl bg-teal-700 px-4 py-2 text-white">ادامه / تلاش مجدد</button><button v-if="session&&!['done'].includes(state)" @click="cancel" class="rounded-xl border px-4 py-2 text-red-700">لغو</button></div><p v-if="state==='uploading'" class="text-sm text-teal-700">در حال بارگذاری…</p><p v-if="state==='finalizing'" class="text-sm text-teal-700">در حال ثبت نهایی…</p><p v-if="state==='done'" class="text-sm text-emerald-700">ویدئو با موفقیت ذخیره شد.</p><p v-if="state==='resume'" class="text-sm text-amber-700">یک بارگذاری ناتمام پیدا شد؛ همان فایل را انتخاب و ادامه دهید.</p></div></div></template>
